questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: [reference longitude (0 Greenwich, 37 Nairobi), reference h, m, ship h, m]. The two Nairobi nodes apply only on Nairobi entries; elsewhere dto = 999 and rfw = -999, values no longitude takes (used only by their tests). Source: original. */
L: [[0,8,0,10,40],[0,12,0,9,12],[37,10,0,12,20],[0,15,30,18,58],[37,9,0,6,24],[0,6,0,2,40],[37,14,0,13,12],[0,20,0,23,0],[37,7,30,4,46],[0,11,15,9,51]];
ix: 1+rand(10);
E: L[ix];
ref: E[1];
gw: is(ref=0);
t0: 60*E[2]+E[3]; ts: 60*E[4]+E[5];
dt: ts-t0;
ahead: is(dt>0);
lam: ref+dt/4;
lon1: abs(lam); ew1: if lam>0 then "E" else "W"; e1: is(lam>0);
/* diagnostics (signed) */
lw: -lam; l15: ref+dt/15;
dto: if gw then 999 else dt/4;
rfw: if gw then -999 else ref-dt/4;
sgl(v) := if v>0 then "E" else "W";
opt2: [["E", e1, "E"], ["W", not e1, "W"]];

feedbackvariables.text:
g: if ans2="E" then ans1 else -ans1;
yt: 4*(g-ref);
c1: is(abs(g-lam)<=0.001);
z1: is(abs(g-lw)<=0.001);
q1: is(abs(g-l15)<=0.001);
n1: is(abs(g-dto)<=0.001);
m1: is(abs(g-rfw)<=0.001);
